CREATE ROLE sales_ro;
GRANT USAGE ON DATABASE analytics TO ROLE sales_ro;
GRANT USAGE ON SCHEMA analytics.sales TO ROLE sales_ro;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics.sales TO ROLE sales_ro;
GRANT SELECT ON FUTURE TABLES IN SCHEMA analytics.sales TO ROLE sales_ro;

CREATE ROLE analyst_sales;
GRANT ROLE sales_ro TO ROLE analyst_sales;
GRANT USAGE ON WAREHOUSE bi_wh TO ROLE analyst_sales;
GRANT ROLE analyst_sales TO ROLE sysadmin;
GRANT ROLE analyst_sales TO USER analyst_01;

CREATE MASKING POLICY governance.policies.mask_email AS (val STRING)
  RETURNS STRING ->
  CASE WHEN IS_ROLE_IN_SESSION('PII_READER') THEN val
       ELSE REGEXP_REPLACE(val, '.+@', '*****@') END;

ALTER TABLE analytics.sales.customers
  MODIFY COLUMN email SET MASKING POLICY governance.policies.mask_email;

CREATE ROW ACCESS POLICY governance.policies.region_rap AS (row_region STRING)
  RETURNS BOOLEAN ->
  EXISTS (SELECT 1 FROM governance.policies.region_entitlements e
          WHERE e.role_name = CURRENT_ROLE() AND e.region = row_region);

ALTER TABLE analytics.sales.orders
  ADD ROW ACCESS POLICY governance.policies.region_rap ON (region);

CREATE TAG governance.tags.pii ALLOWED_VALUES 'email', 'phone', 'name';
ALTER TAG governance.tags.pii SET MASKING POLICY governance.policies.mask_email;
ALTER TABLE analytics.sales.customers
  MODIFY COLUMN email SET TAG governance.tags.pii = 'email';
